109			`{"timestamp":"2026-01-02T00:00:00Z","action":"no-source"}` + "\n" +
110			"   \t \n" +
111			`{"timestamp":"2026-01-02T00:00:00Z","action":"merged-alias","source_ip":"192.0.2.7","src_ip":"::ffff:192.0.2.7"}` + "\n" +
112			`{"timestamp":"not-a-time","action":"bad-time-outside","source_ip":"198.51.100.30"}` + "\n" +
113			`{"timestamp":"2026-12-31T23:59:59-01:00","action":"收尾","msg":"结束🚀","src_ip":"192.0.2.7"}` + "\r\n" +
114			`{"timestamp":"2026-01-02T00:00:00Z","action":"tail-hit","source_ip":"192.0.2.7"}`
115	}
116	
117	// The fixture's business results must hold under every chunking: the six
118	// visible records are the hits on physical lines 1, 3, 8, 10, 11 plus the
119	// failure on line 9; dropped and blank lines leave no record and never
120	// renumber anything; exactly the invalid-timestamp log counts as a failure.
121	func TestNormalizeFilteredChunkedFixtureBusinessResults(t *testing.T) {
122		filter := mustSourceFilter(t, "192.0.2.0/24")
123		input := filteredChunkedFixtureInput()
124		base, failures := assertFilteredChunkingInvariant(t, input, filter)
125		if failures != 1 {
126			t.Fatalf("only the invalid-timestamp log may count as a failure, got %d", failures)
127		}
128	
129		results := decodeResults(t, []byte(base))
130		wantLines := []float64{1, 3, 8, 9, 10, 11}
131		wantOK := []bool{true, true, true, false, true, true}
132		if len(results) != len(wantLines) {
133			t.Fatalf("expected %d records (5 hits + 1 failure), got %d: %#v", len(wantLines), len(results), results)
134		}
135		for i := range wantLines {
136			if results[i]["line"] != wantLines[i] || results[i]["ok"] != wantOK[i] {
137				t.Fatalf("record %d must be line %v ok=%v, got %#v", i, wantLines[i], wantOK[i], results[i])
138			}
139		}
140	
141		// Line 1: aliases map to canonical fields, the timestamp converts to
142		// UTC, the action is trimmed, and extra text keeps its exact characters
143		// even when chunk boundaries fell inside multi-byte UTF-8 or escapes.
144		first := eventOf(t, results[0])
145		if first["timestamp"] != "2026-01-02T00:04:05Z" {
146			t.Fatalf("alias timestamp must convert to UTC, got %v", first["timestamp"])
147		}
148		if first["source_ip"] != "192.0.2.7" {
149			t.Fatalf("alias source_ip mismatch: %v", first["source_ip"])
150		}
151		if first["action"] != "登录" {
152			t.Fatalf("action must be trimmed of surrounding whitespace, got %q", first["action"])
153		}
154		extra := extraOf(t, results[0])
155		if extra["user"] != " 爱丽丝 " {
156			t.Fatalf("extra text must keep its exact characters and spacing, got %q", extra["user"])
157		}
158		if extra["note"] != "换行\n与\"引号\"和中文" {
159			t.Fatalf("extra text with escapes must decode intact, got %q", extra["note"])
160		}
161		if extra["emoji"] != "🚀🙂" {
162			t.Fatalf("emoji must survive chunk boundaries inside UTF-8 sequences, got %q", extra["emoji"])
163		}
164	
165		// Line 3: the mapped spelling normalizes to the same dotted address the
166		// filter matched on; the fractional timestamp is preserved.
167		mapped := eventOf(t, results[1])
168		if mapped["source_ip"] != "192.0.2.7" {
169			t.Fatalf("::ffff:192.0.2.7 must normalize to 192.0.2.7, got %v", mapped["source_ip"])
170		}
171		if mapped["timestamp"] != "2026-01-02T00:00:00.5Z" {
172			t.Fatalf("line 3 timestamp mismatch: %v", mapped["timestamp"])
173		}
174	
175		// Line 8: the canonical name and its alias spelled the same address two
176		// equivalent ways; they merge into exactly one success record.
177		merged := eventOf(t, results[2])
178		if merged["source_ip"] != "192.0.2.7" || merged["action"] != "merged-alias" {
179			t.Fatalf("equivalent canonical/alias spellings must merge into one hit: %#v", merged)
180		}
181	
182		// Line 9: the filter never hides a bad log — the out-of-network source
183		// with an invalid timestamp fails with its physical number and the
184		// timestamp reason, carries no event, and counts as the one failure.
185		if _, exists := results[3]["event"]; exists {
186			t.Fatalf("failed log must not carry an event: %#v", results[3])
187		}
188		msg, _ := results[3]["error"].(string)
189		if !strings.Contains(msg, FieldTimestamp) || !strings.Contains(msg, "invalid RFC3339") {
190			t.Fatalf("failure must keep the timestamp-specific reason, got %q", msg)
191		}
192	
193		// Line 10: CRLF termination and the src_ip alias; the timestamp
194		// converts across the date boundary and the emoji extra survives.
195		tenth := eventOf(t, results[4])
196		if tenth["timestamp"] != "2027-01-01T00:59:59Z" {
197			t.Fatalf("line 10 timestamp must convert to UTC, got %v", tenth["timestamp"])
198		}
199		if extraOf(t, results[4])["msg"] != "结束🚀" {
200			t.Fatalf("line 10 extra mismatch: %#v", extraOf(t, results[4])["msg"])
201		}
202	
203		// Line 11: the final complete JSON without a trailing newline is
204		// processed exactly once, as a hit.
205		if eventOf(t, results[5])["action"] != "tail-hit" {
206			t.Fatalf("final newline-less line must be emitted once as a hit: %#v", results[5])
207		}
208	
209		// Dropped valid logs leave no trace in the output at all.
210		for _, marker := range []string{"out-dropped", "compat-v6", "no-source"} {
211			if strings.Contains(base, marker) {
212				t.Fatalf("dropped line %q must produce no record: %q", marker, base)
213			}
214		}
215	}
216	
217	// Filtering must only remove records, never rewrite them: the filtered
218	// output is exactly the subsequence of the unfiltered results consisting of
219	// every failure plus every admitted success, with identical content.
220	func TestNormalizeFilteredChunkedRecordsAreUnfilteredSubsequence(t *testing.T) {
221		filter := mustSourceFilter(t, "192.0.2.0/24")
222		input := filteredChunkedFixtureInput()
223		base, _ := assertFilteredChunkingInvariant(t, input, filter)
224		filtered := decodeResults(t, []byte(base))
225	
226		var plain bytes.Buffer
227		if _, err := NormalizeReader(strings.NewReader(input), &plain); err != nil {
228			t.Fatalf("unfiltered reference run must not fail, got %v", err)
229		}
230		unfiltered := decodeResults(t, plain.Bytes())
231		var want []map[string]any
232		for _, r := range unfiltered {
233			if r["ok"] != true {
234				want = append(want, r) // failures are always kept
235				continue
236			}
237			event, _ := r["event"].(map[string]any)
238			source, _ := event["source_ip"].(string)
239			if filter.admits(source) {
240				want = append(want, r)
241			}
242		}
243		if !reflect.DeepEqual(filtered, want) {
244			t.Fatalf("filtered records must be the exact unfiltered subsequence\nfiltered:   %#v\nwant: %#v", filtered, want)
245		}
246	}
247	
248	// Splitting the filtered input into exactly two pieces at every possible
249	// byte offset — inside multi-byte characters, inside escape sequences,
250	// between CR and LF — must always reproduce the whole-input filtered output
251	// and failure count.
252	func TestNormalizeFilteredChunkedEveryTwoPieceSplit(t *testing.T) {
253		filter := mustSourceFilter(t, "192.0.2.0/24")
254		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"::ffff:192.0.2.7","event_type":" 登录 ","note":"a\nb\"c\\d中文🚀"}` + "\r\n" +
255			`{"timestamp":"2026-01-02T00:00:00Z","action":"dropped","source_ip":"198.51.100.9"}` + "\n" +
256			`{"timestamp":"bad","action":"bad-time","source_ip":"192.0.2.7"}` + "\n" +
257			`{"timestamp":"2026-01-02T00:00:00Z","action":"尾","source_ip":"192.0.2.7","x":"🙂"}`
258		var whole bytes.Buffer
259		baseFailures, err := NormalizeReaderFiltered(strings.NewReader(input), &whole, filter)
260		if err != nil {
261			t.Fatalf("filtered baseline must not fail, got %v", err)
262		}
263		for i := 0; i <= len(input); i++ {
264			out, failures := normalizeFilteredChunked(t, input, filter, []int{i, len(input) - i})
265			if out != whole.String() || failures != baseFailures {
266				t.Fatalf("split at byte %d changed the filtered result\nwhole:   %q (%d failures)\nchunked: %q (%d failures)",
267					i, whole.String(), baseFailures, out, failures)
268			}
269		}
270	}
271	
272	// A single valid log larger than 64 KiB needs several reads to assemble;
273	// under the filter it is still processed whole: the hit's long unknown
274	// string is preserved verbatim, the dropped line after it stays invisible,
275	// and the following hit keeps its physical line number.
276	func TestNormalizeFilteredChunkedOversizedLine(t *testing.T) {
277		filter := mustSourceFilter(t, "192.0.2.0/24")
278		blob := strings.Repeat("长", 20000) + strings.Repeat("x", 40000) + "🚀"
279		line := `{"timestamp":"2026-01-02T00:00:00Z","action":"big","source_ip":"192.0.2.7","blob":` + jsonString(blob) + `}`
280		if len(line) <= 64*1024 {
281			t.Fatalf("test setup: oversized log must exceed 64 KiB, got %d bytes", len(line))
282		}
283		input := line + "\n" +
284			`{"timestamp":"2026-01-02T00:00:00Z","action":"dropped","source_ip":"198.51.100.9"}` + "\n" +
285			`{"timestamp":"2026-01-02T00:00:00Z","action":"after","source_ip":"192.0.2.7"}` + "\n"
286	
287		base, failures := assertFilteredChunkingInvariant(t, input, filter)
288		if failures != 0 {
289			t.Fatalf("valid logs must report zero failures, got %d", failures)
290		}
291		results := decodeResults(t, []byte(base))
292		if len(results) != 2 {
293			t.Fatalf("expected the oversized hit and the trailing hit only, got %#v", results)
294		}
295		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
296			t.Fatalf("oversized line 1 must succeed: %#v", results[0])
297		}
298		if got := extraOf(t, results[0])["blob"]; got != blob {
299			t.Fatalf("long unknown string must be preserved verbatim (got %d chars, want %d)",
300				len(got.(string)), len(blob))
301		}
302		if results[1]["line"] != float64(3) || results[1]["ok"] != true {
303			t.Fatalf("hit after the dropped line must keep physical line 3: %#v", results[1])
304		}
305		if eventOf(t, results[1])["action"] != "after" {
306			t.Fatalf("hit after the dropped line must keep its content: %#v", results[1])
307		}
308	}
309	
310	// At clean end of input the final complete JSON log is processed exactly
311	// once even without a trailing newline: an admittable tail is emitted, a
312	// dropped tail (out of network, IPv6, or source-less) adds nothing, and a
313	// failing tail counts as one failure — under every chunking.
314	func TestNormalizeFilteredChunkedInputTail(t *testing.T) {
315		filter := mustSourceFilter(t, "192.0.2.0/24")
316		head := `{"timestamp":"2026-01-02T00:00:00Z","action":"head","source_ip":"192.0.2.7"}` + "\n"
317		cases := []struct {
318			name         string
319			tail         string
320			wantResults  int
321			wantFailures int
322			wantLastOK   bool // meaning of the last record when wantResults == 2
323		}{
324			{"admittable tail", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-hit","source_ip":"192.0.2.7"}`, 2, 0, true},
325			{"out-of-network tail", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-out","source_ip":"198.51.100.9"}`, 1, 0, true},
326			{"genuine IPv6 tail", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-v6","source_ip":"::192.0.2.7"}`, 1, 0, true},
327			{"source-less tail", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-none"}`, 1, 0, true},
328			{"invalid-timestamp tail", `{"timestamp":"not-a-time","action":"tail-bad","source_ip":"192.0.2.7"}`, 2, 1, false},
329		}
330		for _, tc := range cases {
331			t.Run(tc.name, func(t *testing.T) {
332				base, failures := assertFilteredChunkingInvariant(t, head+tc.tail, filter)
333				if failures != tc.wantFailures {
334					t.Fatalf("want %d failures, got %d", tc.wantFailures, failures)
335				}
336				results := decodeResults(t, []byte(base))
337				if len(results) != tc.wantResults {
338					t.Fatalf("expected %d results, got %#v", tc.wantResults, results)
339				}
340				last := results[len(results)-1]
341				if tc.wantResults == 2 {
342					// The tail is physical line 2 whenever it produces a record.
343					if last["line"] != float64(2) || last["ok"] != tc.wantLastOK {
344						t.Fatalf("tail record must be line 2 with ok=%v: %#v", tc.wantLastOK, last)
345					}
346				}
347				if tc.wantResults == 1 && eventOf(t, last)["action"] != "head" {
348					t.Fatalf("dropped tail must leave the head record untouched: %#v", last)
349				}
350			})
351		}
352	}
353	
354	// A read fault that delivers only part of the stream must not turn the
355	// unterminated fragment into a record or a failure, no matter how the
356	// complete lines before it were chunked. The emitted prefix equals a
357	// healthy filtered read of exactly the complete lines, and the caller still
358	// receives ErrLogRead wrapping the original cause.
359	func TestNormalizeFilteredChunkedPartialReadFault(t *testing.T) {
360		filter := mustSourceFilter(t, "192.0.2.0/24")
361		complete := strings.Join([]string{
362			`{"timestamp":"2026-01-02T00:00:00Z","action":"in-allowed","source_ip":"192.0.2.7"}`,
363			`{"timestamp":"2026-01-02T00:00:00Z","action":"out-dropped","source_ip":"198.51.100.9"}`,
364			``,
365			`{"timestamp":"not-a-time","action":"bad-time-outside","source_ip":"198.51.100.30"}`,
366		}, "\n") + "\n"
367		fragments := []struct {
368			name     string
369			fragment string
370			marker   string
371		}{
372			{"fragment is a complete admittable object", `{"timestamp":"2026-01-02T00:00:00Z","action":"tail-in-allowed","source_ip":"192.0.2.7"}`, "tail-in-allowed"},
373			{"fragment carries an invalid timestamp", `{"timestamp":"not-a-time","action":"tail-bad-time","source_ip":"192.0.2.7"}`, "tail-bad-time"},
374		}
375		patterns := [][]int{{1}, {7, 4096, 3, 64}, {len(complete)}}
376	
377		var healthy bytes.Buffer
378		healthyFailures, healthyErr := NormalizeReaderFiltered(strings.NewReader(complete), &healthy, filter)
379		if healthyErr != nil || healthyFailures != 1 {
380			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
381		}
382	
383		for _, tc := range fragments {
384			for pi, sizes := range patterns {
385				t.Run(fmt.Sprintf("%s/chunk pattern %d", tc.name, pi), func(t *testing.T) {
386					// Deliver the complete lines in the chunk pattern, then the
387					// unterminated fragment together with the read fault.
388					var steps []scriptStep
389					for pos, step := 0, 0; pos < len(complete); step++ {
390						n := sizes[step%len(sizes)]
391						if n <= 0 {
392							continue
393						}
394						if rem := len(complete) - pos; n > rem {
395							n = rem
396						}
397						steps = append(steps, scriptStep{data: []byte(complete[pos : pos+n])})
398						pos += n
399					}
400					steps = append(steps, scriptStep{data: []byte(tc.fragment), err: errSimulatedRead})
401	
402					var out bytes.Buffer
403					failures, err := NormalizeReaderFiltered(&scriptReader{steps: steps}, &out, filter)
404					if !errors.Is(err, ErrLogRead) || !errors.Is(err, errSimulatedRead) {
405						t.Fatalf("want ErrLogRead wrapping the read cause, got %v", err)
406					}
407					if failures != healthyFailures {
408						t.Fatalf("the failed-read fragment must not add failures: got %d, want %d", failures, healthyFailures)
409					}
410					if !bytes.Equal(out.Bytes(), healthy.Bytes()) {
411						t.Fatalf("output must equal a healthy filtered read of the complete lines:\nfault:   %q\nhealthy: %q", out.String(), healthy.String())
412					}
413					if bytes.Contains(out.Bytes(), []byte(tc.marker)) {
414						t.Fatalf("the unterminated fragment belongs to the failed read and must leave no record: %q", out.String())
415					}
416				})
417			}
418		}
419	}
