	out, failures := runCharsetFiltered(t, input)
	if failures != 0 {
		t.Fatalf("an all-legal all-miss batch must have zero failures, got %d", failures)
	}
	if len(out) != 0 {
		t.Fatalf("every valid log missed the network, so no record may be emitted, got %q", out)
	}
}

